  // Generated enable wires
  wire can_accept_1_en;
  wire done_1_en;
  wire next_state_tx_done_1_en;
  wire next_state_tx_idle_0_en;
  wire tx_done_1_done_1_en;
  wire tx_done_1_en;
  wire tx_done_1_next_state_tx_idle_0_en;
  wire tx_idle_0_can_accept_1_en;
