  assign tx_done_1_done_1_en = tx_done_1_en;  // done <- 1
  // next_state
  assign tx_done_1_next_state_tx_idle_0_en = tx_done_1_en;  // next_state <- TX_IDLE_0


  // === DT: tx_idle_0 ===
