use lib 'perl', 't/lib';
use JSON::PP;
use FSM::Test::ProjectDataLocality;
use FSM::Test::VerilatorRuntime qw(run_verilator_compile run_generated_binary);
my $work = '.artifacts/specforge-feature-intake-20260926';
my @records;
for my $name ('parameter-width', 'parameter-width-64') {
    my $compile = run_verilator_compile(['verilator', '--binary', '--timing', '--assert', '-Wno-fatal', '-j', '1',
        '--top-module', 'width_probe', '--Mdir', "$work/obj_$name", "$work/generic-port-widths/$name.sv", "$work/width_probe.sv"]);
